package com.hsm.integration;
import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service public class SpringMailEmailService implements EmailService { private final JavaMailSender sender; private final String from; private final boolean enabled; public SpringMailEmailService(JavaMailSender s,@Value("${app.mail.from:no-reply@hsm.local}") String f,@Value("${app.mail-enabled:false}") boolean e){sender=s;from=f;enabled=e;} public void sendVerificationCode(String email,String otp){ if(!enabled)return; SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(email);m.setSubject("HSM email verification");m.setText("Your HSM verification code is valid for five minutes.");sender.send(m); } }
